# -*- coding: utf-8 -*-
"""Марочные коды: одинаковый номер у разных марок значит разное, поэтому они лежат отдельно по маркам.

Только то, в чём есть уверенность. Остальные заводские коды получают общее описание семейства
generic_p1/generic_c/generic_b и уходят нейронке на разбор по опыту владельцев.
Ключ марки — см. brandKey() в Kotlin: hyundai_kia, lada, toyota, vag, ford, gm, nissan, honda.
"""
from families import F

BRANDS = {}


def b(brand, c, t, f, m="", causes=None, s=None, d=None, r=None, e="", stop=None):
    assert f in F, (brand, c, f)
    d_ = BRANDS.setdefault(brand, {})
    assert c not in d_, (brand, c)
    entry = {"t": t, "f": f}
    if m: entry["m"] = m
    if e: entry["e"] = e.strip()
    if causes: entry["c"] = causes
    if s: entry["s"] = s
    if d: entry["d"] = d
    if r: entry["r"] = r
    if stop is not None: entry["stop"] = stop
    d_[c] = entry


